'use strict';
const fs = require('fs');
const path = require('path');

const expected = [
  { file: 'a.txt', label: 'Alpha' },
  { file: 'b.txt', label: 'Beta' },
  { file: 'c.txt', label: 'Gamma' },
];

const rows = expected.map(({ file, label }) => {
  const p = path.join(__dirname, file);
  const raw = fs.readFileSync(p, 'utf8');
  const m = raw.match(/^(\w+) population:\s*(\d+)\s*$/);
  if (!m) throw new Error(`${file}: unexpected format ${JSON.stringify(raw)}`);
  const value = Number(m[2]);
  if (m[1] !== label) throw new Error(`${file}: label ${m[1]} != expected ${label}`);
  if (!Number.isInteger(value) || value < 0) throw new Error(`${file}: bad number ${m[2]}`);
  return { file, label: m[1], value };
});

// Independent re-read of the raw bytes to cross-check the parsed numbers.
for (const r of rows) {
  const bytes = fs.statSync(path.join(__dirname, r.file)).size;
  const digitsOnly = fs.readFileSync(path.join(__dirname, r.file), 'utf8').replace(/\D/g, '');
  if (Number(digitsOnly) !== r.value) {
    throw new Error(`${r.file}: parsed ${r.value} != digits ${digitsOnly}`);
  }
  r.bytes = bytes;
}

const total = rows.reduce((s, r) => s + r.value, 0);

// Cross-check the sum with an independent expression.
const altTotal = rows.map(r => r.value).join('+');
if (eval(altTotal) !== total) throw new Error('sum mismatch');

const answer = { total };
fs.writeFileSync(path.join(__dirname, 'answer.json'), JSON.stringify(answer) + '\n', 'utf8');

console.log(JSON.stringify({ rows, expression: altTotal, total }, null, 2));

// Verify the written artifact round-trips.
const back = JSON.parse(fs.readFileSync(path.join(__dirname, 'answer.json'), 'utf8'));
if (typeof back.total !== 'number' || back.total !== total) {
  throw new Error(`answer.json round-trip mismatch: ${JSON.stringify(back)}`);
}
if (Object.keys(back).length !== 1 || !('total' in back)) {
  throw new Error(`answer.json keys unexpected: ${JSON.stringify(Object.keys(back))}`);
}
console.log('OK answer.json total =', back.total);

